* { box-sizing: border-box; }
html { color-scheme: dark; }
html, body { margin: 0; padding: 0; }
body {
  background: var(--bg);
  color: var(--text);
  font: 16px/1.55 ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  min-width: 320px;
}
img, svg { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button { font: inherit; color: inherit; background: none; border: 0; cursor: pointer; }
:focus { outline: none; }
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
  border-radius: 4px;
}

.wrap { width: 100%; max-width: var(--maxw); margin: 0 auto; padding: 0 24px; }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0,0,0,0); white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 12px; top: -40px;
  background: var(--accent); color: var(--accent-ink);
  padding: 8px 12px; border-radius: 6px; font-weight: 600;
  z-index: 100;
}
.skip-link:focus { top: 12px; }

/* ===== Header ===== */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(11, 12, 16, 0.78);
  backdrop-filter: saturate(140%) blur(10px);
  -webkit-backdrop-filter: saturate(140%) blur(10px);
  border-bottom: 1px solid var(--line);
}
.header-inner {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 24px;
  height: 68px;
}
.brand {
  display: inline-flex; align-items: center; gap: 10px;
  font-weight: 700; letter-spacing: 0.02em;
  color: var(--text);
}
.brand-mark { width: 26px; height: 26px; color: var(--accent); }
.brand-word { font-size: 1.05rem; }

.primary-nav ul {
  list-style: none; margin: 0; padding: 0;
  display: flex; gap: 6px; justify-content: center;
}
.primary-nav a {
  display: inline-block;
  padding: 8px 14px; border-radius: 999px;
  color: var(--text-dim);
  font-size: 0.95rem;
  transition: color .15s ease, background .15s ease;
}
.primary-nav a:hover { color: var(--text); background: var(--bg-2); }

.header-actions { display: flex; align-items: center; gap: 8px; }

.search {
  position: relative;
  display: flex; align-items: center;
}
.search-icon {
  position: absolute; left: 10px; width: 18px; height: 18px;
  color: var(--text-mute); pointer-events: none;
}
.search input {
  width: 220px;
  background: var(--bg-2);
  color: var(--text);
  border: 1px solid var(--line);
  padding: 9px 12px 9px 34px;
  border-radius: 999px;
  font-size: 0.92rem;
  transition: border-color .15s, background .15s;
}
.search input::placeholder { color: var(--text-mute); }
.search input:hover { border-color: var(--line-strong); }
.search input:focus-visible { border-color: var(--focus); background: var(--bg-3); outline-offset: 0; }

.icon-btn {
  position: relative;
  display: inline-flex; align-items: center; justify-content: center;
  width: 40px; height: 40px;
  border-radius: 10px;
  color: var(--text-dim);
  border: 1px solid transparent;
  transition: background .15s, color .15s, border-color .15s;
}
.icon-btn:hover { background: var(--bg-2); color: var(--text); border-color: var(--line); }
