/* ===== Hero ===== */
.hero { padding: 56px 0 72px; position: relative; overflow: hidden; }
.hero::before {
  content: ""; position: absolute; inset: 0;
  background:
    radial-gradient(60% 60% at 80% 20%, rgba(201,162,106,0.08), transparent 60%),
