.cat-card[data-cat="accessories"] { --cat-bg: radial-gradient(120% 80% at 80% 20%, #332a1e, #14110c 70%); }
.cat-card[data-cat="grooming"] { --cat-bg: radial-gradient(120% 80% at 20% 20%, #2a2333, #100f18 70%); }
.cat-card[data-cat="outdoor"]  { --cat-bg: radial-gradient(120% 80% at 60% 30%, #1f3030, #0e1414 70%); }
