+.header-inner {
+  display: grid;
+  grid-template-columns: auto 1fr auto;
+  align-items: center;
+  gap: 24px;
+  height: 68px;
+}
+.brand {
+  display: inline-flex; align-items: center; gap: 10px;
+  font-weight: 700; letter-spacing: 0.02em;
+  color: var(--text);
+}
+.brand-mark { width: 26px; height: 26px; color: var(--accent); }
+.brand-word { font-size: 1.05rem; }
+
+.primary-nav ul {
+  list-style: none; margin: 0; padding: 0;
+  display: flex; gap: 6px; justify-content: center;
+}
+.primary-nav a {
+  display: inline-block;
+  padding: 8px 14px; border-radius: 999px;
+  color: var(--text-dim);
+  font-size: 0.95rem;
+  transition: color .15s ease, background .15s ease;
+}
+.primary-nav a:hover { color: var(--text); background: var(--bg-2); }
+
+.header-actions { display: flex; align-items: center; gap: 8px; }
+
+.search {
+  position: relative;
+  display: flex; align-items: center;
+}
+.search-icon {
+  position: absolute; left: 10px; width: 18px; height: 18px;
+  color: var(--text-mute); pointer-events: none;
+}
+.search input {
+  width: 220px;
+  background: var(--bg-2);
+  color: var(--text);
+  border: 1px solid var(--line);
+  padding: 9px 12px 9px 34px;
+  border-radius: 999px;
+  font-size: 0.92rem;
+  transition: border-color .15s, background .15s;
+}
+.search input::placeholder { color: var(--text-mute); }
+.search input:hover { border-color: var(--line-strong); }
+.search input:focus-visible { border-color: var(--focus); background: var(--bg-3); outline-offset: 0; }
+
+.icon-btn {
+  position: relative;
+  display: inline-flex; align-items: center; justify-content: center;
+  width: 40px; height: 40px;
+  border-radius: 10px;
+  color: var(--text-dim);
+  border: 1px solid transparent;
+  transition: background .15s, color .15s, border-color .15s;
+}
+.icon-btn:hover { background: var(--bg-2); color: var(--text); border-color: var(--line); }
+.icon-btn svg { width: 20px; height: 20px; }
+.cart-count {
+  position: absolute; top: 4px; right: 4px;
+  min-width: 18px; height: 18px; padding: 0 5px;
+  background: var(--accent); color: var(--accent-ink);
+  font-size: 11px; font-weight: 700; line-height: 18px;
+  border-radius: 999px; text-align: center;
+}
+
+/* ===== Buttons ===== */
+.btn {
+  display: inline-flex; align-items: center; justify-content: center;
+  gap: 8px; padding: 12px 20px;
+  border-radius: 999px;
+  font-weight: 600; font-size: 0.95rem;
+  border: 1px solid transparent;
+  transition: transform .12s ease, background .15s, color .15s, border-color .15s;
+  white-space: nowrap;
+}
+.btn:active { transform: translateY(1px); }
+.btn-primary {
+  background: var(--accent); color: var(--accent-ink);
+  border-color: var(--accent);
+}
+.btn-primary:hover { background: var(--accent-2); border-color: var(--accent-2); }
+.btn-ghost {
+  background: transparent; color: var(--text);
+  border-color: var(--line-strong);
+}
+.btn-ghost:hover { background: var(--bg-2); border-color: var(--text-mute); }
+
+/* ===== Section heads ===== */
+.section-head {
+  display: flex; align-items: end; justify-content: space-between;
+  gap: 16px; flex-wrap: wrap;
+  margin-bottom: 28px;
+}
+.section-head h2 {
+  font-size: clamp(1.5rem, 2.4vw, 2rem);
+  letter-spacing: -0.01em; margin: 4px 0 0;
+}
+.eyebrow {
+  display: inline-flex; align-items: center; gap: 8px;
+  text-transform: uppercase; letter-spacing: 0.14em;
+  font-size: 0.75rem; font-weight: 600;
+  color: var(--text-mute); margin: 0;
+}
+.eyebrow .dot {
+  width: 6px; height: 6px; border-radius: 50%;
+  background: var(--accent);
+  box-shadow: 0 0 0 4px rgba(201, 162, 106, 0.15);
+}
+.eyebrow-accent { color: var(--accent-2); }
+
+.link-arrow {
+  display: inline-flex; align-items: center; gap: 8px;
+  color: var(--text-dim); font-weight: 500;
+  border-bottom: 1px solid transparent;
+  padding-bottom: 2px;
+}
+.link-arrow:hover { color: var(--text); border-color: var(--line-strong); }
+
+/* ===== Hero ===== */
+.hero { padding: 56px 0 72px; position: relative; overflow: hidden; }
+.hero::before {
+  content: ""; position: absolute; inset: 0;
+  background:
+    radial-gradient(60% 60% at 80% 20%, rgba(201,162,106,0.08), transparent 60%),
+    radial-gradient(50% 50% at 10% 90%, rgba(120, 130, 200, 0.07), transparent 60%);
+  pointer-events: none;
+}
+.hero-inner {
+  position: relative;
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: 48px;
+  align-items: center;
+}
+.hero-copy h1 {
+  font-size: clamp(2.2rem, 5vw, 3.6rem);
+  line-height: 1.05; letter-spacing: -0.02em;
+  margin: 14px 0 18px;
+}
+.lede { color: var(--text-dim); font-size: 1.075rem; max-width: 52ch; margin: 0 0 28px; }
+.hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }
+.hero-meta {
+  list-style: none; margin: 32px 0 0; padding: 18px 0 0;
+  display: flex; gap: 28px; flex-wrap: wrap;
+  border-top: 1px solid var(--line);
+  color: var(--text-dim); font-size: 0.92rem;
+}
+.hero-meta strong { color: var(--text); font-weight: 600; }
+
+.hero-art {
+  position: relative;
+  aspect-ratio: 1 / 1;
+  min-height: 360px;
+}
+.hero-glow {
+  position: absolute; inset: 10%;
+  background: radial-gradient(closest-side, rgba(201,162,106,0.25), transparent 70%);
+  filter: blur(20px);
+  z-index: 0;
+}
+.hero-card {
+  position: absolute;
+  background: var(--bg-2);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  padding: 14px;
+  box-shadow: var(--shadow);
+  width: 56%;
+  z-index: 1;
+}
+.hero-card--a { top: 4%; left: 4%; transform: rotate(-3deg); }
+.hero-card--b { bottom: 4%; right: 4%; transform: rotate(2deg); width: 52%; }
+.hero-card-img {
+  aspect-ratio: 4 / 5;
+  border-radius: 10px;
+  margin-bottom: 12px;
+}
+.hero-card-meta {
+  display: flex; justify-content: space-between;
+  font-size: 0.9rem; color: var(--text-dim);
+}
+.hero-card-meta span:first-child { color: var(--text); font-weight: 500; }
+.tag {
+  display: inline-block;
+  font-size: 0.7rem; letter-spacing: 0.1em; text-transform: uppercase;
+  padding: 4px 8px; border-radius: 999px;
+  background: var(--bg-3); color: var(--text-dim);
+  margin-bottom: 10px;
+}
+.tag-accent { background: var(--accent); color: var(--accent-ink); }
+
+/* Decorative artwork (CSS-only) */
+[data-art] { background-color: var(--bg-3); }
+[data-art="jacket"] {
+  background:
+    linear-gradient(135deg, transparent 40%, rgba(255,255,255,0.04) 41%, transparent 42%),
+    radial-gradient(120% 80% at 50% 20%, #2a2f3e, #161922 70%),
+    #1a1d27;
+}
+[data-art="lamp"] {
+  background:
+    radial-gradient(40% 30% at 50% 28%, rgba(232, 199, 154, 0.55), transparent 70%),
+    linear-gradient(180deg, #1a1d27 60%, #0f1117);
+}
+[data-art="speaker"] {
+  background:
+    radial-gradient(28% 28% at 50% 50%, #2c3142, #1a1d27 70%),
+    radial-gradient(60% 60% at 50% 50%, rgba(201,162,106,0.18), transparent 70%),
+    #14171f;
+}
+[data-art="ed1"] { background: linear-gradient(160deg, #2a2f3e, #14171f 70%), #1a1d27; }
+[data-art="ed2"] { background: linear-gradient(160deg, #3a2f24, #1a1410 70%), #1f1812; }
+[data-art="ed3"] { background: linear-gradient(160deg, #243038, #0f1418 70%), #161c20; }
+[data-art="ed4"] { background: linear-gradient(160deg, #1f3328, #10181a 70%), #131c19; }
+
+/* ===== Categories ===== */
+.categories { padding: 40px 0; border-top: 1px solid var(--line); }
+.cat-grid {
+  list-style: none; padding: 0; margin: 0;
+  display: grid; grid-template-columns: repeat(6, 1fr); gap: 14px;
+}
+.cat-card {
+  display: flex; flex-direction: column; justify-content: end;
+  aspect-ratio: 1 / 1.15;
+  padding: 14px;
+  border-radius: var(--radius);
+  border: 1px solid var(--line);
+  background: var(--bg-1);
+  position: relative; overflow: hidden;
+  transition: transform .2s ease, border-color .15s, background .15s;
+}
+.cat-card::before {
+  content: ""; position: absolute; inset: 0;
+  background: var(--cat-bg, linear-gradient(160deg, #1c2030, #0f1117));
+  opacity: 0.9; transition: opacity .2s;
+}
+.cat-card[data-cat="apparel"] { --cat-bg: radial-gradient(120% 80% at 30% 0%, #2a2233, #11131a 70%); }
+.cat-card[data-cat="home"]    { --cat-bg: radial-gradient(120% 80% at 70% 10%, #233028, #11141a 70%); }
+.cat-card[data-cat="tech"]    { --cat-bg: radial-gradient(120% 80% at 50% 0%, #1f2a3a, #0f1218 70%); }
+.cat-card[data-cat="accessories"] { --cat-bg: radial-gradient(120% 80% at 80% 20%, #332a1e, #14110c 70%); }
+.cat-card[data-cat="grooming"] { --cat-bg: radial-gradient(120% 80% at 20% 20%, #2a2333, #100f18 70%); }
+.cat-card[data-cat="outdoor"]  { --cat-bg: radial-gradient(120% 80% at 60% 30%, #1f3030, #0e1414 70%); }
+.cat-card > * { position: relative; z-index: 1; }
+.cat-card:hover { border-color: var(--line-strong); transform: translateY(-2px); }
+.cat-name { font-size: 1.1rem; font-weight: 600; }
+.cat-count { font-size: 0.82rem; color: var(--text-mute); margin-top: 2px; }
+
+/* ===== Featured / Products ===== */
+.featured { padding: 64px 0 48px; }
+
+.filter-bar { display: flex; gap: 8px; flex-wrap: wrap; }
+.chip {
+  padding: 8px 14px;
+  border-radius: 999px;
+  background: var(--bg-2);
+  color: var(--text-dim);
+  border: 1px solid var(--line);
+  font-size: 0.88rem; font-weight: 500;
+  transition: background .15s, color .15s, border-color .15s;
+}
+.chip:hover { color: var(--text); border-color: var(--line-strong); }
+.chip[aria-selected="true"] {
+  background: var(--text);
+  color: var(--bg);
+  border-color: var(--text);
+}
+
+.product-grid {
+  list-style: none; padding: 0; margin: 0;
+  display: grid; gap: 20px;
+  grid-template-columns: repeat(4, 1fr);
+}
+.product {
+  display: flex; flex-direction: column;
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  transition: transform .2s ease, border-color .15s;
+}
+.product:hover { border-color: var(--line-strong); transform: translateY(-2px); }
+.product-media {
+  position: relative;
+  aspect-ratio: 4 / 5;
+}
+.product-media .badge {
+  position: absolute; top: 10px; left: 10px;
+  padding: 4px 8px; border-radius: 999px;
+  font-size: 0.72rem; font-weight: 700; letter-spacing: 0.06em;
+  background: var(--bg-3); color: var(--text);
+  border: 1px solid var(--line-strong);
+}
+.product-media .badge.sale { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
+.product-media .badge.new { background: #2c3a4d; color: #cfe0ff; border-color: transparent; }
+.product-fav {
+  position: absolute; top: 8px; right: 8px;
+  width: 36px; height: 36px;
+  background: rgba(20, 23, 31, 0.7);
+  border-radius: 999px;
+  border: 1px solid var(--line);
+  color: var(--text-dim);
+  display: inline-flex; align-items: center; justify-content: center;
+  transition: color .15s, background .15s;
+}
+.product-fav:hover { color: var(--text); background: rgba(20, 23, 31, 0.9); }
+.product-fav[aria-pressed="true"] { color: var(--accent); }
+.product-fav svg { width: 18px; height: 18px; }
+
+.product-body { padding: 14px 16px 16px; display: flex; flex-direction: column; gap: 6px; }
+.product-cat { font-size: 0.72rem; color: var(--text-mute); text-transform: uppercase; letter-spacing: 0.12em; }
+.product-name { margin: 0; font-size: 1rem; font-weight: 600; }
+.product-name a { color: var(--text); }
+.product-name a:hover { color: var(--accent-2); }
+.product-meta {
+  display: flex; align-items: center; justify-content: space-between;
+  margin-top: 6px;
+}
+.price { margin: 0; display: flex; align-items: baseline; gap: 8px; }
+.price-now { font-weight: 700; font-size: 1.05rem; color: var(--text); }
+.price-was { color: var(--text-mute); text-decoration: line-through; font-size: 0.9rem; }
+
+.rating { display: inline-flex; align-items: center; gap: 4px; color: var(--accent-2); font-size: 0.85rem; }
+.rating .count { color: var(--text-mute); }
+
+/* product placeholder art */
+.p-art {
+  width: 100%; height: 100%;
+  background: linear-gradient(160deg, var(--p-a, #2a2f3e), var(--p-b, #14171f));
+  position: relative;
+}
+.p-art::after {
+  content: ""; position: absolute; inset: 0;
+  background: radial-gradient(40% 30% at 50% 50%, rgba(255,255,255,0.06), transparent 70%);
+}
+
+/* ===== Deals ===== */
+.deals {
+  padding: 64px 0;
+  background:
+    linear-gradient(180deg, var(--bg) 0%, var(--bg-1) 50%, var(--bg) 100%);
+  border-top: 1px solid var(--line);
+  border-bottom: 1px solid var(--line);
+}
+.countdown {
+  display: inline-flex; align-items: center; gap: 6px;
+  background: var(--bg-2);
+  border: 1px solid var(--line);
+  padding: 8px 12px;
+  border-radius: 12px;
+  font-variant-numeric: tabular-nums;
+}
+.cd-unit { display: inline-flex; flex-direction: column; align-items: center; min-width: 36px; }
+.cd-num { font-weight: 700; font-size: 1.05rem; color: var(--text); }
+.cd-lbl { font-size: 0.65rem; text-transform: uppercase; letter-spacing: 0.12em; color: var(--text-mute); }
+.cd-sep { color: var(--text-mute); margin-top: -10px; }
+
+.deals-grid {
+  display: grid;
+  grid-template-columns: 1.1fr 1fr;
+  gap: 20px;
+  align-items: stretch;
+}
+.deal-feature {
+  position: relative;
+  display: grid; grid-template-rows: 1fr auto;
+  background: var(--bg-2);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  min-height: 360px;
+}
+.deal-feature .badge {
+  position: absolute; top: 14px; left: 14px;
+  background: var(--accent); color: var(--accent-ink);
+  padding: 6px 10px; border-radius: 999px;
+  font-weight: 700; font-size: 0.78rem; letter-spacing: 0.08em;
+  z-index: 1;
+}
+.deal-art { background-color: var(--bg-3); }
+.deal-feature .deal-art { min-height: 220px; }
+.deal-body { padding: 18px 20px 22px; display: flex; flex-direction: column; gap: 10px; }
+.deal-body h3 { margin: 4px 0 0; font-size: 1.4rem; letter-spacing: -0.01em; }
+.deal-body p { color: var(--text-dim); margin: 0; }
+.deal-body .btn { align-self: start; margin-top: 8px; }
+
+.deal-list { list-style: none; margin: 0; padding: 0; display: grid; gap: 14px; }
+.deal-row {
+  display: grid;
+  grid-template-columns: 88px 1fr auto;
+  gap: 14px; align-items: center;
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  padding: 12px;
+  transition: border-color .15s, transform .15s;
+}
+.deal-row:hover { border-color: var(--line-strong); transform: translateY(-1px); }
+.deal-row .deal-thumb {
+  width: 88px; height: 88px; border-radius: 10px;
+}
+.deal-row h3 { margin: 0; font-size: 1rem; font-weight: 600; }
+.deal-row h3 a { color: var(--text); }
+.deal-row h3 a:hover { color: var(--accent-2); }
+.deal-row .meta { color: var(--text-mute); font-size: 0.85rem; margin: 4px 0 0; }
+.deal-row .price { margin-top: 8px; }
+.deal-row .badge {
+  background: var(--bg-3); color: var(--text); border: 1px solid var(--line-strong);
+  padding: 4px 8px; border-radius: 999px; font-size: 0.75rem; font-weight: 700;
+}
+
+/* ===== Editorial ===== */
+.editorial { padding: 72px 0 48px; }
+.editorial-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr;
+  grid-template-rows: auto auto;
+  gap: 20px;
+}
+.ed {
+  background: var(--bg-1);
+  border: 1px solid var(--line);
+  border-radius: var(--radius);
+  overflow: hidden;
+  transition: border-color .15s, transform .2s;
+}
+.ed:hover { border-color: var(--line-strong); transform: translateY(-2px); }
+.ed-link { display: flex; flex-direction: column; height: 100%; color: inherit; }
+.ed-art { aspect-ratio: 16 / 10; }
+.ed-body { padding: 18px 20px 22px; }
+.ed-body h3 { margin: 8px 0 6px; font-size: 1.15rem; letter-spacing: -0.01em; }
+.ed-body p { color: var(--text-dim); margin: 0; }
+.ed-meta { display: flex; align-items: center; gap: 10px; color: var(--text-mute); font-size: 0.82rem; }
+.ed-tag {
+  background: var(--bg-3); color: var(--text);
+  padding: 3px 8px; border-radius: 999px;
+  font-size: 0.72rem; letter-spacing: 0.08em; text-transform: uppercase;
+  border: 1px solid var(--line-strong);
+}
+.ed-lead { grid-row: span 2; }
+.ed-lead .ed-art { aspect-ratio: 4 / 5; }
+.ed-lead .ed-body h3 { font-size: 1.6rem; }
+
+/* ===== CTA band / Newsletter ===== */
+.cta-band {
+  padding: 56px 0;
+  background:
+    radial-gradient(80% 100% at 0% 0%, rgba(201,162,106,0.08), transparent 60%),
+    var(--bg-1);
+  border-top: 1px solid var(--line);
+}
+.cta-inner {
+  display: grid; grid-template-columns: 1fr 1fr; gap: 32px;
+  align-items: center;
+}
+.cta-band h2 { margin: 0 0 8px; font-size: clamp(1.4rem, 2.5vw, 1.9rem); }
+.cta-band p { color: var(--text-dim); margin: 0; max-width: 50ch; }
+.newsletter {
+  display: grid; grid-template-columns: 1fr auto; gap: 10px;
+  align-items: start;
+}
+.newsletter input {
+  width: 100%;
+  padding: 14px 16px;
+  background: var(--bg-2);
+  color: var(--text);
+  border: 1px solid var(--line);
+  border-radius: 999px;
+  font-size: 1rem;
+}
+.newsletter input::placeholder { color: var(--text-mute); }
+.newsletter input:hover { border-color: var(--line-strong); }
+.newsletter input:focus-visible { border-color: var(--focus); outline-offset: 0; }
+.newsletter input[aria-invalid="true"] { border-color: var(--danger); }
+.form-msg {
+  grid-column: 1 / -1;
+  margin: 4px 4px 0; min-height: 1.2em;
+  font-size: 0.88rem; color: var(--text-dim);
+}
+.form-msg.is-error { color: var(--danger); }
+.form-msg.is-success { color: var(--success); }
+
+/* ===== Footer ===== */
+.site-footer {
+  padding: 56px 0 28px;
+  background: var(--bg);
+  border-top: 1px solid var(--line);
+  margin-top: 8px;
+}
+.footer-grid {
+  display: grid;
+  grid-template-columns: 1.4fr 1fr 1fr 1fr;
+  gap: 40px;
+  padding-bottom: 36px;
+}
+.footer-brand p { color: var(--text-dim); max-width: 36ch; margin-top: 12px; }
+.footer-h {
+  font-size: 0.82rem; letter-spacing: 0.14em; text-transform: uppercase;
+  color: var(--text-mute); margin: 0 0 14px; font-weight: 600;
+}
+.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 8px; }
+.site-footer a { color: var(--text-dim); }
+.site-footer a:hover { color: var(--text); }
+.footer-bottom {
+  display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap;
+  padding-top: 24px;
+  border-top: 1px solid var(--line);
+  color: var(--text-mute); font-size: 0.85rem;
+}
+
+/* ===== Reflow / responsive ===== */
+@media (max-width: 1080px) {
+  .product-grid { grid-template-columns: repeat(3, 1fr); }
+  .cat-grid { grid-template-columns: repeat(3, 1fr); }
+  .editorial-grid { grid-template-columns: 1fr 1fr; }
+  .ed-lead { grid-row: auto; grid-column: span 2; }
+  .ed-lead .ed-art { aspect-ratio: 16 / 9; }
+}
+@media (max-width: 860px) {
+  .header-inner { grid-template-columns: auto auto; height: auto; padding: 14px 0; gap: 12px; }
+  .primary-nav { order: 3; grid-column: 1 / -1; overflow-x: auto; }
+  .primary-nav ul { justify-content: start; flex-wrap: nowrap; }
+  .search input { width: 160px; }
+  .hero-inner { grid-template-columns: 1fr; gap: 32px; }
+  .hero-art { min-height: 320px; }
+  .deals-grid { grid-template-columns: 1fr; }
+  .cta-inner { grid-template-columns: 1fr; }
+  .footer-grid { grid-template-columns: 1fr 1fr; gap: 28px; }
+}
+@media (max-width: 620px) {
+  .product-grid { grid-template-columns: repeat(2, 1fr); }
+  .cat-grid { grid-template-columns: repeat(2, 1fr); }
+  .editorial-grid { grid-template-columns: 1fr; }
+  .ed-lead { grid-column: auto; }
+  .footer-grid { grid-template-columns: 1fr 1fr; }
